  const cleanKey = apiKey.trim();
  if (!cleanKey) return true;

  const now = Date.now();
  if (now < rateLimitUntil) return true;
  if (cleanKey === lastInvalidKey && now < invalidKeyUntil) return true;

  return false;
}

